//! En-route units (FIS and ACC sectors) generated by the airport wizard into `enroute.toml`.

use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::station::StationError;

/// What an en-route unit is.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum EnrouteKind {
    Fis,
    Acc,
}

/// One sector of an en-route unit; limits are feet AMSL.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SectorDef {
    pub name: String,
    pub lower_ft: i32,
    pub upper_ft: i32,
    /// Boundary vertices as `[lat, lon]`.
    pub polygon: Vec<[f64; 2]>,
}

/// An en-route unit: one callsign on one frequency, covering one or more sectors.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct EnrouteUnitDef {
    pub callsign: String,
    pub khz: u32,
    pub kind: EnrouteKind,
    pub sectors: Vec<SectorDef>,
}

#[derive(Serialize, Deserialize)]
struct File {
    #[serde(default)]
    units: Vec<EnrouteUnitDef>,
}

/// Serialises units as the `enroute.toml` body (no header comment).
pub fn to_toml(units: &[EnrouteUnitDef]) -> Result<String, toml::ser::Error> {
    toml::to_string(&File {
        units: units.to_vec(),
    })
}

/// Loads `enroute.toml`; an absent file is no units.
pub fn load_enroute(path: &Path) -> Result<Vec<EnrouteUnitDef>, StationError> {
    let text = match std::fs::read_to_string(path) {
        Ok(t) => t,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(e) => {
            return Err(StationError::Io {
                file: path.display().to_string(),
                reason: e.to_string(),
            });
        }
    };
    let file: File = toml::from_str(&text).map_err(|e| StationError::Toml {
        file: path.display().to_string(),
        line: e.span().map(|s| text[..s.start].matches('\n').count() + 1),
        reason: e.message().to_string(),
    })?;
    Ok(file.units)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn unit() -> EnrouteUnitDef {
        EnrouteUnitDef {
            callsign: "Testland Information".into(),
            khz: 120_500,
            kind: EnrouteKind::Fis,
            sectors: vec![SectorDef {
                name: "FIS TESTLAND-NORTH".into(),
                lower_ft: 0,
                upper_ft: 9500,
                polygon: vec![[50.0, 20.0], [50.0, 21.0], [51.0, 21.0], [50.0, 20.0]],
            }],
        }
    }

    #[test]
    fn enroute_round_trips() {
        let dir = std::env::temp_dir().join(format!("vatc-enroute-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("enroute.toml");
        let units = vec![unit()];
        std::fs::write(&path, format!("# header\n{}", to_toml(&units).unwrap())).unwrap();
        assert_eq!(load_enroute(&path).unwrap(), units);
        std::fs::remove_dir_all(&dir).unwrap();
    }

    #[test]
    fn absent_file_is_empty() {
        let p = std::env::temp_dir().join("vatc-no-such-enroute.toml");
        assert!(load_enroute(&p).unwrap().is_empty());
    }

    #[test]
    fn bad_file_is_an_error_with_a_line() {
        let dir = std::env::temp_dir().join(format!("vatc-enroute-bad-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("enroute.toml");
        std::fs::write(&path, "[[units]]\ncallsign = 1\n").unwrap();
        assert!(matches!(
            load_enroute(&path),
            Err(StationError::Toml { line: Some(_), .. })
        ));
        std::fs::remove_dir_all(&dir).unwrap();
    }
}
